const PASS={
 evs:{t:`गद्यांश: ज़ीरो घाटी के धान-मछली खेत`,x:`अरुणाचल प्रदेश की ज़ीरो घाटी में आपातानी नाम की जनजाति रहती है। यहाँ के लोग सदियों से एक अनोखे ढंग से खेती करते आ रहे हैं। वे पहाड़ी झरनों और छोटी नदियों का पानी नालियों और बाँस की नलियों के सहारे अपने धान के खेतों तक पहुँचाते हैं। धान के खेतों में भरे इसी पानी में वे छोटी-छोटी मछलियाँ भी पालते हैं। मछलियाँ खेत के कीड़ों और खरपतवार को खा जाती हैं और उनका मल फ़सल के लिए खाद का काम करता है। इसलिए किसानों को रासायनिक खाद और कीटनाशक दवाओं की बहुत कम ज़रूरत पड़ती है। धान कटने के समय लोगों को चावल के साथ मछलियाँ भी मिल जाती हैं। एक ही खेत से दो तरह का भोजन मिलने के कारण इस ढंग को धान-मछली खेती कहा जाता है। घाटी के लोग अपने आसपास के जंगलों को भी बहुत सँभालकर रखते हैं, क्योंकि उन्हीं के कारण झरनों में साल भर पानी बना रहता है।`},
 l1:{t:`गद्यांश 1`,x:`गर्मी की छुट्टियों में अमर पहली बार अकेले बाज़ार गया। माँ ने उसे पाँच सौ रुपये का नोट देकर आटा, दाल और साबुन लाने को कहा था। सामान तौलने के बाद दुकानदार रामू काका ने जल्दी-जल्दी में उसे बाक़ी पैसे लौटा दिए। घर आकर अमर ने पैसे गिने, तो वे पूरे सौ रुपये ज़्यादा निकले। उसका मन ललचा गया। उन सौ रुपयों से वह वही नई गेंद ख़रीद सकता था, जिसका वह कई दिनों से सपना देख रहा था। फिर उसे याद आया कि रामू काका की दुकान बहुत छोटी है और वे दिन भर धूप में बैठकर मेहनत करते हैं। शाम को वह चुपचाप दुकान पर गया और सौ रुपये लौटा दिए। उन्होंने बताया कि दिन भर का हिसाब मिलाते समय वे इसी कमी से परेशान थे। उन्होंने अमर के सिर पर हाथ रखकर कहा, “बेटा, आज तुमने मेरा घाटा ही नहीं बचाया, मेरा भरोसा भी जीत लिया।” घर लौटते समय अमर के हाथ में गेंद नहीं थी, पर उसका मन बहुत हल्का था।`},
 l2:{t:`गद्यांश 2`,x:`डॉ. होमी जहाँगीर भाभा का जन्म 30 अक्टूबर 1909 को मुंबई में हुआ था। बचपन से ही उन्हें गणित और विज्ञान के साथ-साथ चित्रकला और संगीत में भी गहरी रुचि थी। उच्च शिक्षा के लिए वे इंग्लैंड के कैम्ब्रिज विश्वविद्यालय गए और वहाँ भौतिकी में शोध किया। भारत लौटकर उन्होंने सोचा कि देश को विज्ञान में आगे बढ़ाने के लिए हमें अपने ही वैज्ञानिक तैयार करने होंगे। इसी सोच से सन् 1945 में मुंबई में “टाटा मूलभूत अनुसंधान संस्थान” की स्थापना हुई। सन् 1948 में बने परमाणु ऊर्जा आयोग के वे पहले अध्यक्ष बने। उन्होंने परमाणु ऊर्जा का उपयोग बिजली बनाने जैसे शांतिपूर्ण कामों में करने पर ज़ोर दिया। 24 जनवरी 1966 को एक विमान दुर्घटना में उनका निधन हो गया। उनके सम्मान में ट्रॉम्बे के परमाणु ऊर्जा संस्थान का नाम “भाभा परमाणु अनुसंधान केंद्र” रखा गया। आज उन्हें भारत के परमाणु ऊर्जा कार्यक्रम का जनक कहा जाता है।`},
 l3:{t:`गद्यांश 3`,x:`गर्मी की छुट्टियों में हम सब नानी के गाँव गए थे। वहाँ रात को बिजली कम ही आती थी, इसलिए सब लोग छत पर चारपाइयाँ बिछाकर सोते थे। दिन भर की तपन के बाद रात की ठंडी हवा बहुत सुहानी लगती थी। जैसे-जैसे अँधेरा गहराता, आकाश में तारे एक-एक करके जगमगाने लगते। शहर में तो धुएँ और तेज़ रोशनी के कारण गिने-चुने तारे ही दिखते थे, पर यहाँ पूरा आकाश मानो चाँदी के अनगिनत दानों से भरा थाल हो। नानी उँगली से दिखातीं, “वह देखो, सात तारों का झुंड — सप्तर्षि; और वह उत्तर में अकेला, पर एक ही जगह स्थिर चमकता ध्रुव तारा।” कभी-कभी कोई टूटता तारा आकाश में चमकीली लकीर खींचकर पलक झपकते ही ग़ायब हो जाता। दूर खेतों से झींगुरों की लगातार झनकार आती रहती और कहीं-कहीं जुगनू अपनी हरी-पीली रोशनी टिमटिमाते हुए उड़ते। हम तारे गिनते-गिनते कब सो जाते, पता ही न चलता।`},
 l4:{t:`गद्यांश 4`,x:`हर बच्चे के मन में ढेरों प्रश्न होते हैं — आकाश नीला क्यों है, पक्षी कैसे उड़ते हैं, बादल कहाँ से आते हैं। प्रश्न पूछने और नई बातें जानने की यही इच्छा जिज्ञासा कहलाती है। जिज्ञासा ज्ञान का पहला दरवाज़ा है। जो बच्चा प्रश्न पूछता है, वह केवल उत्तर याद नहीं करता, बल्कि बातों को गहराई से समझता है। कहा जाता है कि पेड़ से सेब गिरते तो बहुत लोगों ने देखा था, पर न्यूटन ने पूछा कि सेब नीचे ही क्यों गिरता है, ऊपर क्यों नहीं जाता। इसी प्रश्न ने उन्हें गुरुत्वाकर्षण के नियम तक पहुँचाया। कई बच्चे कक्षा में प्रश्न पूछने से डरते हैं, क्योंकि उन्हें लगता है कि दूसरे उन पर हँसेंगे। पर सीखने के लिए पूछा गया कोई भी प्रश्न छोटा या बेकार नहीं होता। पुस्तकें, प्रयोग और बड़ों से बातचीत — ये सब हमारे प्रश्नों के उत्तर खोजने के साधन हैं। जो प्रश्न पूछना नहीं छोड़ता, वह सीखना भी कभी नहीं छोड़ता।`}
};
